                                                            'either be a value of a sample.Domain object.\n'
                                                            '\n'
                                                            '\n'
                                                            '\n'
                                                            '```python\n'
                                                            'custom_hp = {\n'
                                                            '    "transformer_ms": {\n'
                                                            '        "model_path": {\n'
                                                            '            "domain": "albert-base-v2",\n'
