                  'gpu_ids: Optional[str] = None, timing_params: Optional[dict] = None, configs_list: '
                  'Optional[Sequence[str]] = None, inner_blend: Optional[lightautoml.automl.blend.Blender] = '
                  'None, outer_blend: Optional[lightautoml.automl.blend.Blender] = None, drop_last: bool = True, '
