                '            n_train_iter = 100\n'
                '\n'
                '            for step in range(n_train_iter):\n'
                '                clf.partial_fit(X_train, y_train, classes=classes)\n'
                '\n'
                '                intermediate_value = clf.score(X_valid, y_valid)\n'
                '                trial.report(intermediate_value, step)\n'
                '\n'
