                '        import optuna\n'
                '        from optuna.storages import GrpcStorageProxy\n'
                '\n'
                '        storage = GrpcStorageProxy(host="localhost", port=13000)\n'
                '        study = optuna.create_study(storage=storage)\n'
                '\n'
