                                                         "- ``'records'`` : list like\n"
                                                         '  ``[{column -> value}, ... , {column -> value}]``\n'
                                                         "- ``'index'`` : dict like ``{index -> {column -> "
                                                         'value}}``\n'
                                                         "- ``'columns'`` : dict like ``{column -> {index -> "
                                                         'value}}``\n'
                                                         "- ``'values'`` : just the values array\n"
                                                         "- ``'table'`` : dict like ``{'schema': {schema}, "
                                                         "'data': {data}}``\n"
                                                         '\n'
                                                         'The allowed and default values depend on the value\n'
