                '\n'
                '>>> df = pl.DataFrame(\n'
                '...     {\n'
                '...         "a": [1, 2, 3, 4],\n'
                '...         "b": [0.5, 4, 10, 13],\n'
                '...         "c": [True, True, False, True],\n'
