                '| tcp        | TCP                                                |\n'
                '| tcp4       | TCP over IPv4                                      |\n'
                '| tcp6       | TCP over IPv6                                      |\n'
                '| udp        | UDP                                                |\n'
                '| udp4       | UDP over IPv4                                      |\n'
                '| udp6       | UDP over IPv6                                      |\n'
