                                                      'phase : int\n'
                                                      '    The phase of the optimization being executed. In '
                                                      'phase 1 a basic\n'
                                                      '    feasible solution is sought and the T has an '
                                                      'additional row\n'
                                                      '    representing an alternate objective function.\n'
                                                      'status : int\n'
                                                      '    An integer representing the exit status of the '
                                                      'optimization::\n'
                                                      '\n'
                                                      '         0 : Optimization terminated successfully\n'
                                                      '         1 : Iteration limit reached\n'
                                                      '         2 : Problem appears to be infeasible\n'
                                                      '         3 : Problem appears to be unbounded\n'
                                                      '         4 : Serious numerical difficulties encountered\n'
                                                      '\n'
                                                      'nit : int\n'
                                                      '    The number of iterations performed.\n'
                                                      'message : str\n'
                                                      '    A string descriptor of the exit status of the '
                                                      'optimization.',
