                                                        '- 1}{\\text{stride}[0]} + 1\\right\\rfloor\n'
                                                        '\n'
                                                        '  .. math::\n'
                                                        '      W_{out} = \\left\\lfloor\\frac{W_{in}  + 2 '
                                                        '\\times \\text{padding}[1] - \\text{dilation}[1]\n'
                                                        '                \\times (\\text{kernel\\_size}[1] - 1) '
