                                                            '\n'
                                                            '.. code-block:: python\n'
                                                            '\n'
                                                            '    for params in parameters_grid:\n'
                                                            '        # be sure to (re)initialize the callbacks '
                                                            'before each run\n'
                                                            '        callbacks = '
                                                            '[xgb.callback.LearningRateScheduler(custom_rates)]\n'
                                                            '        reg = xgboost.XGBRegressor(**params, '
