                                                             '    # Show all messages, including ones pertaining '
                                                             'to debugging\n'
                                                             '    xgb.set_config(verbosity=2)\n'
                                                             '\n'
                                                             '    # Get current value of global configuration\n'
                                                             '    # This is a dict containing all parameters in '
                                                             'the global configuration,\n'
                                                             "    # including 'verbosity'\n"
                                                             '    config = xgb.get_config()\n'
                                                             "    assert config['verbosity'] == 2\n"
                                                             '\n'
                                                             '    # Example of using the context manager '
                                                             'xgb.config_context().\n'
                                                             '    # The context manager will restore the '
                                                             'previous value of the global\n'
                                                             '    # configuration upon exiting.\n'
                                                             '    with xgb.config_context(verbosity=0):\n'
                                                             '        # Suppress warning caused by model '
                                                             'generated with XGBoost version < 1.0.0\n'
                                                             '        bst = '
                                                             "xgb.Booster(model_file='./old_model.bin')\n"
                                                             "    assert xgb.get_config()['verbosity'] == 2  # "
                                                             'old value restored\n'
                                                             '\n'
                                                             'Nested configuration context is also supported:\n'
                                                             '\n'
                                                             'Example\n'
                                                             '-------\n'
                                                             '\n'
                                                             '.. code-block:: python\n'
                                                             '\n'
                                                             '    with xgb.config_context(verbosity=3):\n'
                                                             '        assert xgb.get_config()["verbosity"] == 3\n'
                                                             '        with xgb.config_context(verbosity=2):\n'
                                                             '            assert xgb.get_config()["verbosity"] '
                                                             '== 2\n'
                                                             '\n'
                                                             '    xgb.set_config(verbosity=2)\n'
                                                             '    assert xgb.get_config()["verbosity"] == 2\n'
                                                             '    with xgb.config_context(verbosity=3):\n'
                                                             '        assert xgb.get_config()["verbosity"] == 3',
